{
  "findings": [
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "A parent reports that Microsoft may share collected data with third parties like Facebook, Media.net, Outbrain, Taboola, and Yahoo for advertising purposes.",
      "stance": "risk",
      "quote": "Advertisers sometimes include their own or other advertising partners’ web beacons within their ads that we display, enabling them to set and read their own cookies. In some cases, we share reports with advertisers about the data we have collected on their sites or ads. Additionally, Microsoft partners with Xandr (a Microsoft Company) and third-party ad companies to help provide some of our advertising services, and we also allow other third-party ad companies to display advertisements on our sites. These third parties may place cookies on your devices and collect data about your online activities across websites or online services. These companies currently include, but are not limited to: [Facebook](https://www.facebook.com/help/568137493302217), [Media.net](https://www.media.net/adchoices), [Outbrain](https://my.outbrain.com/recommendations-settings/home), [Taboola](https://www.taboola.com/privacy-policy) and [Yahoo](https://legal.yahoo.com/xw/en/yahoo/privacy/intl/index.html)."
    },
    {
      "ref": "[D527]",
      "area": "data",
      "claim": "A parent reports that Microsoft may retain diagnostic data for troubleshooting and product improvement, and users can control optional diagnostic data.",
      "stance": "mitigation",
      "quote": "Many Microsoft products collect diagnostic data to keep our services secure and up-to-date; help ensure they work as expected; detect, diagnose, and fix problems; and improve our products. Diagnostic data can include information about crashes, performance, and your usage of our products. There are two levels of diagnostic data: required diagnostic data and optional diagnostic data. Products that collect diagnostic data will always collect required diagnostic data, but you can control whether to send us optional diagnostic data."
    },
    {
      "ref": "[D527]",
      "area": "age_gating",
      "claim": "A parent reports that Microsoft does not appear to have an age gate for its services.",
      "stance": "risk",
      "quote": "Microsoft receives and responds to the Global Privacy Control (GPC) browser opt-out signal in certain jurisdictions. Microsoft will turn off sharing your data with third parties for personalized ads and turn off the “Share my data with third parties for personalized ads” toggle if we receive a GPC signal from you when you visit our sites."
    }
  ]
}
